@Composable fun tr(e:String,h:String)=if(LocalHindi.current)h else e
@Composable fun spName(s:String)=tr(s, listOf("गाय","भैंस","बकरी","भेड़","खरगोश","मुर्गी","कुत्ता","अन्य").getOrElse(species.indexOf(s)){s})
@Composable fun stName(s:String)=tr(s,listOf("स्वस्थ","बीमार","ठीक हो रहा","अज्ञात").getOrElse(statuses.indexOf(s)){s})
@Composable fun typeName(k:String)=tr(careTypes[k]?:k, mapOf("health" to "स्वास्थ्य जांच","vaccine" to "टीकाकरण","deworm" to "कृमिनाशन","breeding" to "प्रजनन","production" to "दूध और वृद्धि","feed" to "चारा और पोषण","finance" to "आय और खर्च")[k]?:k)
fun glyph(k:String):ImageVector=when(k){"home"->Icons.Outlined.Home;"animals"->Icons.Outlined.Pets;"records"->Icons.Outlined.Assignment;"reports"->Icons.Outlined.BarChart;"settings"->Icons.Outlined.Settings;"health"->Icons.Outlined.MonitorHeart;"vaccine"->Icons.Outlined.Vaccines;"deworm"->Icons.Outlined.Medication;"production"->Icons.Outlined.WaterDrop;"feed"->Icons.Outlined.Grass;"finance"->Icons.Outlined.CurrencyRupee;"breeding"->Icons.Outlined.FavoriteBorder;"calendar"->Icons.Outlined.CalendarMonth;"check"->Icons.Outlined.CheckCircle;else->Icons.Outlined.Pets}
fun datePretty(s:String)=runCatching{LocalDate.parse(s).format(DateTimeFormatter.ofPattern("dd MMM yyyy"))}.getOrDefault(s)
