@Composable fun PashuApp(model:RegisterModel=viewModel()){
 val s by model.state.collectAsStateWithLifecycle();val data=s.register
 CompositionLocalProvider(LocalHindi provides data.hindi){
 val nav=rememberNavController();val entry by nav.currentBackStackEntryAsState();val route=entry?.destination?.route?:"home";val tabs=listOf("home","animals","records","reports","settings")
 val snackbar=remember{SnackbarHostState()};val scope=rememberCoroutineScope()
 LaunchedEffect(s.error,s.ready){if(s.ready&&s.error!=null){snackbar.showSnackbar(s.error!!);model.clearError()}}
 fun go(k:String){nav.navigate(k){popUpTo("home"){saveState=true};launchSingleTop=true;restoreState=true}}
 fun addAnimal(){nav.navigate("animal/new")}
 fun openAnimal(a:String){nav.navigate("profile/"+a)}
 fun addCare(k:String,a:String="new"){if(data.animals.isEmpty())addAnimal() else nav.navigate("care/"+k+"/"+a+"/new")}
 fun saved(text:String){scope.launch{snackbar.showSnackbar(text)}}
 Scaffold(containerColor=CanvasBg,snackbarHost={SnackbarHost(snackbar)},topBar={
  if(s.ready&&route in tabs) Header(onLanguage={model.language(!data.hindi)})
 },bottomBar={if(s.ready&&route in tabs)NavigationBar(containerColor=Color.White,tonalElevation=0.dp){
  tabs.forEach{k->val label=when(k){"home"->tr("Home","होम");"animals"->tr("Animals","पशु");"records"->tr("Care","देखभाल");"reports"->tr("Reports","रिपोर्ट");else->tr("Settings","सेटिंग")};NavigationBarItem(selected=route==k,onClick={go(k)},icon={Icon(glyph(k),null)},label={Text(label,fontSize=11.sp)},colors=NavigationBarItemDefaults.colors(indicatorColor=Mint,selectedIconColor=Green,selectedTextColor=Green,unselectedIconColor=Muted,unselectedTextColor=Muted))}
 }}){pad->
 Box(Modifier.fillMaxSize().padding(pad)){
  when{
   s.loading -> LoadingScreen()
   !s.ready -> Column(Modifier.fillMaxSize().padding(30.dp),verticalArrangement=Arrangement.Center){Icon(Icons.Outlined.ErrorOutline,null,tint=Rust,modifier=Modifier.size(42.dp));Spacer(Modifier.height(16.dp));Text(tr("Unable to open your register","रजिस्टर नहीं खुल सका"),style=MaterialTheme.typography.headlineMedium);Text(s.error?:tr("Please try again.","फिर कोशिश करें।"),color=Muted);Spacer(Modifier.height(20.dp));Button(onClick={model.load()}){Text(tr("Retry","फिर कोशिश करें"))}}
   else -> NavHost(navController=nav,startDestination="home",enterTransition={fadeIn()+slideInHorizontally{it/14}},exitTransition={fadeOut()},popEnterTransition={fadeIn()},popExitTransition={fadeOut()}){
    composable("home"){Dashboard(data,{addAnimal()},{addCare(it)},{openAnimal(it)},{go("animals")},{go("reports")},{model.demo()})}
    composable("animals"){AnimalsPage(data,{addAnimal()},{openAnimal(it)})}
    composable("records"){RecordsPage(data,{addCare(it)},{c->nav.navigate("care/"+c.type+"/"+c.animalId+"/"+c.id)},{model.removeCare(it)})}
    composable("reports"){ReportsPage(data)}
    composable("settings"){SettingsPage(data,model,{saved(it)})}
    composable("profile/{aid}"){back->val a=data.animals.find{it.id==back.arguments?.getString("aid")};if(a!=null)ProfilePage(a,data,{nav.popBackStack()},{nav.navigate("animal/"+a.id)},{addCare(it,a.id)},{c->nav.navigate("care/"+c.type+"/"+a.id+"/"+c.id)},{model.removeCare(it)},{model.removeAnimal(a.id){nav.popBackStack()}})else MissingPage{nav.popBackStack()}}
    composable("animal/{aid}"){back->val aid=back.arguments?.getString("aid");val a=data.animals.find{it.id==aid};AnimalForm(a,s.saving,{nav.popBackStack()}){f->model.saveAnimal(f){newId->nav.popBackStack();if(a==null)openAnimal(newId);saved(if(data.hindi)"पशु सहेजा गया" else "Animal saved")}}}
    composable("care/{kind}/{aid}/{cid}"){back->val k=back.arguments?.getString("kind")?:"health";val a=back.arguments?.getString("aid");val c=data.care.find{it.id==back.arguments?.getString("cid")};CareForm(k,a,data,c,s.saving,{nav.popBackStack()}){f->model.saveCare(f){nav.popBackStack();saved(if(data.hindi)"रिकॉर्ड सहेजा गया" else "Care record saved")}}}
   }
  }
  if(s.saving)Box(Modifier.fillMaxSize().background(Color.Black.copy(alpha=.25f)).clickable(enabled=true,onClick={}),contentAlignment=Alignment.Center){Surface(shape=RoundedCornerShape(24.dp),color=Color.White,shadowElevation=8.dp){Column(Modifier.padding(28.dp),horizontalAlignment=Alignment.CenterHorizontally){CircularProgressIndicator(color=Green);Spacer(Modifier.height(18.dp));Text(tr("Saving your records…","रिकॉर्ड सहेज रहे हैं…"),fontWeight=FontWeight.SemiBold);Text(tr("Keep the app open","ऐप खुला रखें"),fontSize=12.sp,color=Muted)}}}
 }
 }
 }
}
